'use client';

import { importLibrary } from '@googlemaps/js-api-loader';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { Point } from '../property-search/area';
import { setupGoogleMaps } from '../property-search/components/google-loader';
import { distanceMeters, sampleRoute } from './geometry';

type WalkLocation = { point: Point; title: string; synthetic?: boolean; path?: Point[] };
export type { WalkLocation };

export function SurroundingsWalk({ location, onClose, onPosition }: {
  location: WalkLocation;
  onClose(): void;
  onPosition(point: Point): void;
}) {
  const footer = useRef<HTMLElement>(null);
  const target = useRef<HTMLDivElement>(null);
  const back = useRef<HTMLButtonElement>(null);
  const viewer = useRef<google.maps.StreetViewPanorama | null>(null);
  const sequence = useRef(0);
  const previousPano = useRef<string | undefined>(undefined);
  const lastPosition = useRef<Point | undefined>(undefined);
  const walked = useRef(0);
  const callbacks = useRef({ onClose, onPosition });
  const [library, setLibrary] = useState<google.maps.StreetViewLibrary>();
  const [status, setStatus] = useState<'loading' | 'ready' | 'gap'>('loading');
  const [playing, setPlaying] = useState(false);
  const [goal, setGoal] = useState(500);
  const [meters, setMeters] = useState(0);
  const [date, setDate] = useState<string>();
  const [message, setMessage] = useState('');
  const [index, setIndex] = useState(0);
  const checkpoints = useMemo(() => location.path ? sampleRoute(location.path, goal) : [], [location.path, goal]);
  const requestedPoint = checkpoints[index]?.point ?? location.point;

  useEffect(() => { callbacks.current = { onClose, onPosition }; }, [onClose, onPosition]);

  useEffect(() => {
    const focused = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    back.current?.focus();
    const escape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') callbacks.current.onClose();
    };
    document.addEventListener('keydown', escape);
    return () => {
      document.removeEventListener('keydown', escape);
      focused?.focus({ preventScroll: true });
    };
  }, []);

  useEffect(() => {
    const caption = footer.current;
    const stage = caption?.closest<HTMLElement>('.map-stage');
    if (!caption || !stage) return;
    const observer = new ResizeObserver(() => {
      stage.style.setProperty('--walk-footer-height', `${caption.getBoundingClientRect().height}px`);
    });
    observer.observe(caption);
    return () => {
      observer.disconnect();
      stage.style.removeProperty('--walk-footer-height');
    };
  }, []);

  useEffect(() => {
    let mounted = true;
    const key = process.env.NEXT_PUBLIC_GOOGLE_MAPS_KEY;
    if (!key) { setStatus('gap'); return; }
    setupGoogleMaps(key);
    importLibrary('streetView').then(result => {
      if (mounted) setLibrary(result);
    }).catch(() => { if (mounted) setStatus('gap'); });
    return () => {
      mounted = false;
      sequence.current += 1;
      if (viewer.current) {
        google.maps.event.clearInstanceListeners(viewer.current);
        viewer.current.setVisible(false);
      }
    };
  }, []);

  const show = useCallback(async (request: google.maps.StreetViewLocationRequest | google.maps.StreetViewPanoRequest) => {
    if (!library) return;
    const generation = ++sequence.current;
    setStatus('loading');
    setMessage('');
    let timeout: ReturnType<typeof setTimeout> | undefined;
    try {
      const service = new library.StreetViewService();
      const response = await Promise.race([
        service.getPanorama(request),
        new Promise<never>((_, reject) => { timeout = setTimeout(() => reject(new Error('Coverage timeout')), 10000); }),
      ]);
      if (generation !== sequence.current || !target.current) return;
      const { data } = response;
      if (!data.location?.pano) throw new Error('No panorama');
      if (!viewer.current) {
        viewer.current = new library.StreetViewPanorama(target.current, {
          pano: data.location.pano, addressControl: false, fullscreenControl: false,
          imageDateControl: true, motionTracking: false, linksControl: true,
          panControl: true, zoomControl: true, clickToGo: true,
        });
        viewer.current.addListener('position_changed', () => {
          const point = viewer.current?.getPosition()?.toJSON();
          if (!point) return;
          if (lastPosition.current) walked.current += distanceMeters(lastPosition.current, point);
          lastPosition.current = point;
          setMeters(Math.round(walked.current));
          callbacks.current.onPosition(point);
        });
      } else {
        const current = viewer.current.getPano();
        if (current !== data.location.pano) previousPano.current = current;
        viewer.current.setPano(data.location.pano);
        viewer.current.setVisible(true);
      }
      setDate(data.imageDate);
      setStatus('ready');
      requestAnimationFrame(() => {
        if (generation === sequence.current && viewer.current) google.maps.event.trigger(viewer.current, 'resize');
      });
    } catch {
      if (generation === sequence.current) {
        setPlaying(false);
        setStatus('gap');
        viewer.current?.setVisible(false);
      }
    } finally { clearTimeout(timeout); }
  }, [library]);

  useEffect(() => {
    if (!library) return;
    previousPano.current = undefined;
    lastPosition.current = undefined;
    walked.current = 0;
    setMeters(0);
    void show({ location: requestedPoint, radius: 80, sources: [google.maps.StreetViewSource.OUTDOOR] });
  }, [library, show, requestedPoint.lat, requestedPoint.lng]);

  const advance = useCallback(() => {
    if (location.path) {
      if (index < checkpoints.length - 1) setIndex(current => current + 1);
      else { setPlaying(false); setMessage('You reached the viewing distance.'); }
      return;
    }
    const panorama = viewer.current;
    if (!panorama) return;
    const heading = panorama.getPov().heading;
    const angle = (link: google.maps.StreetViewLink) => Math.abs((((link.heading ?? heading) - heading) + 540) % 360 - 180);
    const next = (panorama.getLinks() ?? [])
      .filter((link): link is google.maps.StreetViewLink => link !== null)
      .filter(link => link.pano && link.pano !== previousPano.current && angle(link) < 110)
      .sort((a, b) => angle(a) - angle(b))[0];
    if (!next?.pano) {
      setPlaying(false);
      setMessage('No connected view ahead. Look in another direction or return to the map.');
      return;
    }
    if (next.heading != null) panorama.setPov({ heading: next.heading, pitch: panorama.getPov().pitch });
    void show({ pano: next.pano });
  }, [location.path, index, checkpoints.length, show]);

  const progress = location.path ? checkpoints[index]?.meters ?? 0 : meters;
  const complete = location.path ? index >= checkpoints.length - 1 : meters >= goal;

  useEffect(() => {
    if (complete) setPlaying(false);
    if (!playing || status !== 'ready' || complete) return;
    const timer = setTimeout(advance, 3500);
    return () => clearTimeout(timer);
  }, [playing, status, complete, advance]);

  return (
    <section className="surroundings-walk" aria-label="Explore surroundings">
      <header className="walk-header">
        <div><h2>{location.title}</h2><p>First-person street exploration</p></div>
        <button ref={back} className="light" type="button" onClick={onClose}>Back to map</button>
      </header>
      <div className="walk-toolbar">
        <button type="button" disabled={status !== 'ready' || complete} onClick={() => setPlaying(value => !value)}>
          {playing ? 'Pause walking' : 'Start walking'}
        </button>
        <button className="light" type="button" disabled={status === 'loading' || complete} onClick={advance}>Step forward</button>
        <label>Viewing distance
          <select value={goal} onChange={event => { setPlaying(false); setGoal(Number(event.target.value)); setIndex(0); }}>
            {[100, 200, 500, 1000].map(value => <option key={value} value={value}>{value} m</option>)}
          </select>
        </label>
        <span role="status">{progress} m explored{complete ? ' · Viewing distance reached' : ''}</span>
      </div>
      <div className="walk-scene">
        <div ref={target} className="walk-panorama" aria-label="First-person Street View" />
        {status === 'loading' && <div className="walk-feedback" role="status">Finding street imagery near this location…</div>}
        {status === 'gap' && <div className="walk-feedback" role="status">
          <p>Street imagery is unavailable here.</p>
          {location.path && index < checkpoints.length - 1
            ? <button type="button" onClick={advance}>Try next route viewpoint</button>
            : <button type="button" onClick={onClose}>Choose another location on the map</button>}
        </div>}
      </div>
      <footer ref={footer} className="walk-caption">
        <p>{message || 'Drag to look around. Step forward or start walking in the direction you are facing.'}</p>
        <p>Historical Google Street View · {date ? `Requested imagery ${date}` : 'Imagery date unavailable'} · Coverage varies.
          {location.synthetic && ' Starting from a fictional listing location.'}</p>
      </footer>
    </section>
  );
}
